// ─── PARSER FlareSolverr ─────────────────────────────────────────────────────
// FlareSolverr retourne { status, solution: { response: '...HTML...' } }
// On lit solution.response pour avoir le HTML de la page après résolution Cloudflare

const FOOD_KEYWORDS = [
  'lait','yaourt','fromage','beurre','crème','oeuf','oeufs','feta','mozzarella',
  'camembert','emmental','comté','chèvre','ricotta','mascarpone',
  'poulet','boeuf','porc','veau','agneau','saumon','thon','crevette','cabillaud',
  'jambon','lardons','bacon','saucisse','merguez','chipolata','canard','steak',
  'tomate','carotte','courgette','oignon','salade','poireau','brocoli','poivron',
  'avocat','concombre','champignon','épinard','aubergine','haricot',
  'pomme','banane','orange','poire','fraise','raisin','melon','pêche','citron','ananas',
  'pâtes','riz','farine','pain','baguette','céréales','lentilles','quinoa','semoule',
  'huile','sauce tomate','moutarde','mayonnaise','ketchup','vinaigre',
  'eau','jus','café','thé','bière','vin','sirop',
  'pizza','surgelé','conserve','maïs','soupe','confiture','miel','chocolat',
  'escalope','nuggets','côte','filet','poitrine','cuisse',
];

const CATEGORY_MAP = [
  [['fruit','légume','carotte','poivron','salade','courgette','tomate','concombre','épinard','brocoli','oignon','ail','poireau','aubergine','champignon','avocat','banane','poire','pêche','fraise','cerise','raisin','melon','ananas','orange','citron','pomme de terre'], 'Fruits & Légumes'],
  [['viande','boucherie','poulet','boeuf','porc','veau','agneau','côte','steak','filet','canard','lapin','dinde','rôti','escalope','nuggets','poitrine','cuisse'], 'Viandes & Poissons'],
  [['poisson','saumon','thon','crevette','cabillaud','moule','huître','dorade','bar','truite','sardine'], 'Viandes & Poissons'],
  [['lait','yaourt','fromage','beurre','crème','laitier','oeuf','feta','emmental','camembert','chèvre','mozzarella','ricotta'], 'Produits Laitiers'],
  [['surgelé','congel','glace'], 'Surgelés'],
  [['pain','boulang','viennoiserie','brioche','baguette','croissant','madeleine'], 'Boulangerie'],
  [['bière','vin','eau','jus','boisson','soda','café','thé','sirop','cidre','champagne'], 'Boissons'],
  [['jambon','charcuterie','saucisson','lardons','bacon','rillette','pâté','chorizo','merguez'], 'Charcuterie'],
];

const CHAIN_HINTS = [
  ['carrefour','Carrefour'],
  ['lidl','Lidl'],
  ['intermarche','Intermarché'],['intermarché','Intermarché'],
  ['auchan','Auchan'],['leclerc','Leclerc'],
  ['super u','Super U'],['monoprix','Monoprix'],
];

function guessCategory(t) {
  const l = t.toLowerCase();
  for (const [kws, cat] of CATEGORY_MAP) if (kws.some(k => l.includes(k))) return cat;
  return 'Épicerie';
}

function isFood(t) {
  const l = t.toLowerCase();
  return FOOD_KEYWORDS.some(k => l.includes(k)) || CATEGORY_MAP.some(([kws]) => kws.some(k => l.includes(k)));
}

function nextSunday() {
  const d = new Date();
  d.setDate(d.getDate() + (7 - d.getDay() || 7));
  return d.toISOString().split('T')[0];
}

function cleanName(n) {
  return n.replace(/\d+\s*(g|kg|ml|cl|l|litres?|pièces?|unités?|x\d+)/gi, '').replace(/[\s]+/g, ' ').trim();
}

function guessChain(html) {
  const l = html.substring(0, 5000).toLowerCase();
  for (const [k, v] of CHAIN_HINTS) if (l.includes(k)) return v;
  return 'Inconnu';
}

function stripHtml(html) {
  return html
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ').replace(/&#\d+;/g,'')
    .replace(/[ \t]+/g,' ').trim();
}

const deals = [];

for (const input of $input.all()) {
  // FlareSolverr → solution.response contient le HTML
  const rawHtml = String(
    input.json?.solution?.response ||
    input.json?.data ||
    input.json?.html ||
    ''
  );
  if (rawHtml.length < 500) continue;

  const chainName = guessChain(rawHtml);

  // ── 1. JSON-LD schema.org Product ────────────────────────────────────────────
  const jsonLdRx = /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  let foundJsonLd = false;
  while ((m = jsonLdRx.exec(rawHtml)) !== null) {
    try {
      const data = JSON.parse(m[1]);
      const items = Array.isArray(data) ? data : (data['@graph'] || [data]);
      for (const item of items) {
        const type = Array.isArray(item['@type']) ? item['@type'][0] : item['@type'];
        if (!['Product','Offer'].includes(type)) continue;
        const name = cleanName(String(item.name || ''));
        if (name.length < 3 || !isFood(name)) continue;
        const offer = item.offers || item;
        const price = parseFloat(String(offer.price ?? offer.lowPrice ?? offer.minPrice ?? '0').replace(',','.'));
        if (!price || price <= 0 || price > 300) continue;
        foundJsonLd = true;
        deals.push({
          item: name.charAt(0).toUpperCase() + name.slice(1).toLowerCase(),
          chain: chainName,
          brand: typeof item.brand?.name === 'string' ? item.brand.name : null,
          price_promo: Math.round(price * 100) / 100,
          price_normal: null, unit: null,
          valid_until: nextSunday(), region: 'national',
          category: guessCategory(name),
        });
      }
    } catch {}
  }

  // ── 2. Fallback : regex prix dans le texte ───────────────────────────────────
  if (!foundJsonLd) {
    const text = stripHtml(rawHtml);
    const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 2);
    for (const line of lines) {
      const pm = [...line.matchAll(/(\d{1,3}[,.]\d{2})\s*€/g)];
      if (!pm.length) continue;
      let name = line.substring(0, line.indexOf(pm[0][0])).replace(/[-–—:|]/g, ' ').trim();
      name = cleanName(name);
      if (name.length < 3 || name.length > 80 || !isFood(name + ' ' + line)) continue;
      const pp = parseFloat(pm[0][1].replace(',', '.'));
      const pn = pm.length > 1 ? parseFloat(pm[1][1].replace(',', '.')) : null;
      if (isNaN(pp) || pp <= 0 || pp > 200) continue;
      const um = line.match(/(le\s+kg|la\s+pièce|\d+\s*g\b|\d+\s*kg\b|\d+\s*cl\b|\d+\s*l\b|\d+\s*ml\b)/i);
      deals.push({
        item: name.charAt(0).toUpperCase() + name.slice(1).toLowerCase(),
        chain: chainName, brand: null,
        price_promo: Math.round(pp * 100) / 100,
        price_normal: pn && pn > pp ? Math.round(pn * 100) / 100 : null,
        unit: um ? um[0].trim() : null,
        valid_until: nextSunday(), region: 'national',
        category: guessCategory(name),
      });
    }
  }
}

// ── Dédoublonner ─────────────────────────────────────────────────────────────
const seen = new Map(), deduped = [];
for (const d of deals) {
  const key = `${d.item.toLowerCase().slice(0,25)}-${d.chain.toLowerCase()}`;
  const ex = seen.get(key);
  if (!ex || d.price_promo < ex.price_promo) {
    if (ex) deduped.splice(deduped.indexOf(ex), 1);
    seen.set(key, d); deduped.push(d);
  }
}

return [{ json: { deals: deduped, count: deduped.length, sources: ['carrefour.fr','lidl.fr','intermarche.com'] } }];
